class RecordingLedger : Ledger {
    private val balances = mutableMapOf<String, Long>()
    private val journal = mutableListOf<Operation>()

    override fun deposit(id: String, amount: Long) {
        balances.merge(id, amount, Long::plus)          // working behaviour
        journal += Operation("deposit", id, amount)     // recorded interaction
    }

    fun recorded(): List<Operation> = journal.toList()   // test-only accessor
}
